/** Session ownership belongs to the embedding host, not to t3 orchestration repositories. */
export interface ProviderAuthSessionInvalidationRequest {
  readonly requestingInstanceId: ProviderInstanceId;
  readonly instanceId: ProviderInstanceId;
  readonly credentialBinding?: NonNullable<ProviderAuthController["credentialBinding"]>;
  /** Recheck immediately before draining: an affected peer may have rebound while the host awaited cleanup. */
  readonly isCurrent: Effect.Effect<boolean, ProviderSetupError>;
}
export class ProviderAuthSessionInvalidation extends Context.Service<
  ProviderAuthSessionInvalidation,
  {
    readonly invalidateSessions: (
      input: ProviderAuthSessionInvalidationRequest,
    ) => Effect.Effect<void, ProviderSetupError>;
  }
>()("t3/provider/ProviderAuthSessionInvalidation") {}

for (const affectedId of affectedIds) {
  const isCurrent = affectedId === instanceId
    ? Effect.succeed(true)
    : Effect.gen(function* () {
        const current = yield* registry.getInstance(affectedId);
        return binding !== undefined &&
          current?.auth?.credentialBinding?.key === binding.key &&
          current.auth.credentialBinding.owner === binding.owner;
      });
  if (!(yield* isCurrent)) continue;
  yield* sessionInvalidation.invalidateSessions({
    requestingInstanceId: instanceId,
    instanceId: affectedId,
    ...(binding ? { credentialBinding: binding } : {}),
    isCurrent,
  }).pipe(
    Effect.mapError(() => failure("Could not stop all sessions for this provider. Try again.")),

before:
const released = new Set<ProviderSessionId>();
yield* Effect.forEach(
  threadIds,
  (threadId) =>
    projections.getThreadRecords(threadId, ["providerSessions"]).pipe(
      Effect.flatMap((projection) =>
        Effect.forEach(
          projection.providerSessions.filter(
            (session) =>
              affectedIds.has(session.providerInstanceId) &&
              session.status !== "stopped" &&
              session.status !== "error" &&
              !released.has(session.id),
          ),
          (session) =>
            Effect.gen(function* () {
              if (session.providerInstanceId !== instanceId) {
                const current = yield* registry.getInstance(session.providerInstanceId);
                if (
                  !binding ||
                  current?.auth?.credentialBinding?.key !== binding.key ||
                  current.auth.credentialBinding.owner !== binding.owner
                )
                  return;
              }
              yield* providerSessions
                .release({
                  providerSessionId: session.id,
                  reason: "manual_shutdown",
                  detail: "Provider sign-in changed.",
                })
                .pipe(Effect.tap(() => Effect.sync(() => released.add(session.id))));
            }),
          { discard: true },
        ),
      ),
      Effect.mapError(() =>
        failure("Could not stop all sessions for this provider. Try again."),
      ),
    ),
  { discard: true },
);
